-- Layercake.usp_report_payment_method_coverage (src/sql/Layercake/Procedures/Layercake.usp_report_payment_method_coverage.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_payment_method_coverage
    @as_of_date date = NULL
AS
/*
    Count-only payment method coverage (REQ-014, RULE-067, AC-014-01), one row per Campaign Year
    from 2021 and basis that has at least one row.
    - basis 'Paid position': Layercake.silv_payment_events rows (contact_no, campaign_year), with
      the payment method of that contact-year's silv_member_year_attributes row; no attributes row
      is 0 Unknown (ASM-007).
    - basis = event_type: Layercake.silv_membership_events rows by their own campaign_year, with
      the event's own payment_method_id (ASM-007).
    Covered means payment_method_id > 0, so Unknown (0), Unrecognised (-1) and Not applicable (-2)
    are not covered. coverage_pct = with_method / total x 100, rounded to 1 dp.
    @as_of_date is accepted and ignored: every report takes one (ADR-003); coverage covers every year.
    Aggregates only (RULE-066).
*/
BEGIN
    SET NOCOUNT ON;

    WITH positions AS (
        SELECT
            pe.campaign_year,
            CAST('Paid position' AS varchar(20)) AS basis,
            ISNULL(ya.payment_method_id, 0) AS payment_method_id
        FROM Layercake.silv_payment_events AS pe
        LEFT JOIN Layercake.silv_member_year_attributes AS ya
            ON ya.contact_no = pe.contact_no
            AND ya.campaign_year = pe.campaign_year
        WHERE pe.campaign_year >= 2021

        UNION ALL

        SELECT
            ev.campaign_year,
            CAST(ev.event_type AS varchar(20)) AS basis,
            ev.payment_method_id
        FROM Layercake.silv_membership_events AS ev
        WHERE ev.campaign_year >= 2021
    ),

    basis_counts AS (
        SELECT
            p.campaign_year,
            p.basis,
            COUNT(*) AS total,
            COUNT(CASE WHEN p.payment_method_id > 0 THEN 1 END) AS with_method
        FROM positions AS p
        GROUP BY p.campaign_year, p.basis
    )

    SELECT
        bc.campaign_year,
        bc.basis,
        bc.total,
        bc.with_method,
        CAST(ROUND(100.0 * bc.with_method / bc.total, 1) AS decimal(5, 1)) AS coverage_pct
    FROM basis_counts AS bc
    ORDER BY
        bc.campaign_year,
        CASE bc.basis
            WHEN 'Paid position' THEN 0
            WHEN 'Join' THEN 1
            WHEN 'Readmission' THEN 2
            WHEN 'Renewal' THEN 3
            WHEN 'Change' THEN 4
            WHEN 'Lapse' THEN 5
            ELSE 6
        END,
        bc.basis;
END;
GO
-- Layercake.usp_report_invoiced_subtotal_coverage (src/sql/Layercake/Procedures/Layercake.usp_report_invoiced_subtotal_coverage.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_invoiced_subtotal_coverage
    @as_of_date date = NULL
AS
/*
    Count-only invoiced subtotal coverage (REQ-014, RULE-068, AC-014-02), one row per Campaign Year
    that has a Join, Renewal or Readmission event in Layercake.silv_membership_events (its own
    campaign_year, no lower year bound). Change and Lapse carry no amount and are left out.
    Covered means invoiced_subtotal_gbp IS NOT NULL, so 0.00 is covered.
    coverage_pct = with_invoiced_subtotal / events x 100, rounded to 1 dp.
    Then one count per amount_status value (Q-045, AC-015-04).
    @as_of_date is accepted and ignored: every report takes one (ADR-003); coverage covers every year.
    Aggregates only (RULE-066).
*/
BEGIN
    SET NOCOUNT ON;

    WITH year_counts AS (
        SELECT
            ev.campaign_year,
            COUNT(*) AS events,
            COUNT(ev.invoiced_subtotal_gbp) AS with_invoiced_subtotal,
            COUNT(CASE WHEN ev.amount_status = 'Before invoice data' THEN 1 END) AS before_invoice_data,
            COUNT(CASE WHEN ev.amount_status = 'No invoice' THEN 1 END) AS no_invoice,
            COUNT(CASE WHEN ev.amount_status = 'Counted on another event' THEN 1 END) AS counted_on_another_event,
            COUNT(CASE WHEN ev.amount_status = 'Full Concession' THEN 1 END) AS full_concession,
            COUNT(CASE WHEN ev.amount_status = 'Fully credited' THEN 1 END) AS fully_credited,
            COUNT(CASE WHEN ev.amount_status = 'Invoiced' THEN 1 END) AS invoiced
        FROM Layercake.silv_membership_events AS ev
        WHERE ev.event_type IN ('Join', 'Renewal', 'Readmission')
        GROUP BY ev.campaign_year
    )

    SELECT
        yc.campaign_year,
        yc.events,
        yc.with_invoiced_subtotal,
        CAST(ROUND(100.0 * yc.with_invoiced_subtotal / yc.events, 1) AS decimal(5, 1)) AS coverage_pct,
        yc.before_invoice_data,
        yc.no_invoice,
        yc.counted_on_another_event,
        yc.full_concession,
        yc.fully_credited,
        yc.invoiced
    FROM year_counts AS yc
    ORDER BY yc.campaign_year;
END;
GO
-- Layercake.usp_report_direct_debit_share (src/sql/Layercake/Procedures/Layercake.usp_report_direct_debit_share.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_direct_debit_share
    @as_of_date date = NULL
AS
/*
    Count-only Direct Debit share (REQ-014, RULE-069, AC-014-03): one row for the current Campaign
    Year, the ref_campaign_year_config row covering @as_of_date (NULL = today, ADR-003). The report
    fails (50014, as usp_report_top_employers) if no year covers the date.
    - Partially Paid position: a Layercake.silv_payment_events row for that year with
      invoice_position 'Partially Paid'.
    - Direct Debit: payment method id 1 (seeded 'Direct Debit', MOD-003) in that contact-year's
      silv_member_year_attributes row; no attributes row is 0 Unknown (ASM-007).
    direct_debit_share_pct = direct_debit_positions / partially_paid_positions x 100, rounded to
    1 dp, NULL when there are no Partially Paid positions; the row is still returned (ASM-007).
    Aggregates only (RULE-066).
*/
BEGIN
    SET NOCOUNT ON;

    DECLARE @report_date date = ISNULL(@as_of_date, CAST(SYSDATETIME() AS date));
    DECLARE @current_year int;

    SELECT @current_year = cy.campaign_year
    FROM Layercake.ref_campaign_year_config AS cy
    WHERE @report_date BETWEEN cy.campaign_year_start AND cy.campaign_year_end;

    IF @current_year IS NULL
        THROW 50014, N'usp_report_direct_debit_share: no Campaign Year covering @as_of_date in Layercake.ref_campaign_year_config.', 1;

    WITH positions AS (
        SELECT
            COUNT(*) AS partially_paid_positions,
            COUNT(CASE WHEN ya.payment_method_id = 1 THEN 1 END) AS direct_debit_positions
        FROM Layercake.silv_payment_events AS pe
        LEFT JOIN Layercake.silv_member_year_attributes AS ya
            ON ya.contact_no = pe.contact_no
            AND ya.campaign_year = pe.campaign_year
        WHERE pe.campaign_year = @current_year
            AND pe.invoice_position = N'Partially Paid'
    )

    SELECT
        @current_year AS campaign_year,
        p.partially_paid_positions,
        p.direct_debit_positions,
        CAST(
            ROUND(100.0 * p.direct_debit_positions / NULLIF(p.partially_paid_positions, 0), 1) AS decimal(5, 1)
        ) AS direct_debit_share_pct
    FROM positions AS p;
END;
GO
-- Layercake.usp_report_last_full_year_totals (src/sql/Layercake/Procedures/Layercake.usp_report_last_full_year_totals.sql)
CREATE OR ALTER PROCEDURE Layercake.usp_report_last_full_year_totals
    @as_of_date date = NULL
AS
/*
    Count-only totals for the last full Campaign Year (REQ-014, RULE-070, AC-014-04 to AC-014-06),
    as one long-form result set (campaign_year, measure, category, value), so it can be captured
    with INSERT ... EXEC (ASM-007).
    - Last full Campaign Year: the ref_campaign_year_config year before the one covering
      @as_of_date (NULL = today, ADR-003), as in usp_report_top_employers. The report fails (50014)
      if no year covers the date or none precedes it.
    - Paid member: a Layercake.silv_payment_events row for that year. Payment method, payer type and
      concession come from that contact-year's silv_member_year_attributes row; no attributes row is
      0 Unknown.
    - 'paid_members_by_payment_method' / 'paid_members_by_concession_type': one row per method /
      concession type with at least one paid member, category = its name (reserved ids included).
    - 'corporate_paid_members': payer type 2 Corporate (seeded, MOD-004), not the payment method.
    - 'corporate_share_pct': corporate / paid members x 100, rounded to 1 dp; NULL with no paid members.
    - 'invoiced_subtotal_gbp_total' / 'subs_amount_gbp_total': SUM of each column over that year's
      Join, Renewal and Readmission events in silv_membership_events (NULL when nothing to add).
    The four single measures are always returned, with category NULL. Aggregates only (RULE-066).
*/
BEGIN
    SET NOCOUNT ON;

    DECLARE @report_date date = ISNULL(@as_of_date, CAST(SYSDATETIME() AS date));
    DECLARE @last_full_year int;

    SELECT @last_full_year = MAX(prev.campaign_year)
    FROM Layercake.ref_campaign_year_config AS cur
    INNER JOIN Layercake.ref_campaign_year_config AS prev
        ON prev.campaign_year < cur.campaign_year
    WHERE @report_date BETWEEN cur.campaign_year_start AND cur.campaign_year_end;

    IF @last_full_year IS NULL
        THROW 50014, N'usp_report_last_full_year_totals: no Campaign Year before the one covering @as_of_date in Layercake.ref_campaign_year_config.', 1;

    WITH paid_members AS (
        SELECT
            ISNULL(ya.payment_method_id, 0) AS payment_method_id,
            ISNULL(ya.payer_type_id, 0) AS payer_type_id,
            ISNULL(ya.concession_type_id, 0) AS concession_type_id
        FROM Layercake.silv_payment_events AS pe
        LEFT JOIN Layercake.silv_member_year_attributes AS ya
            ON ya.contact_no = pe.contact_no
            AND ya.campaign_year = pe.campaign_year
        WHERE pe.campaign_year = @last_full_year
    ),

    corporate AS (
        SELECT
            COUNT(*) AS paid_members,
            COUNT(CASE WHEN pm.payer_type_id = 2 THEN 1 END) AS corporate_paid_members
        FROM paid_members AS pm
    ),

    amounts AS (
        SELECT
            SUM(ev.invoiced_subtotal_gbp) AS invoiced_subtotal_gbp_total,
            SUM(ev.subs_amount_gbp) AS subs_amount_gbp_total
        FROM Layercake.silv_membership_events AS ev
        WHERE ev.campaign_year = @last_full_year
            AND ev.event_type IN ('Join', 'Renewal', 'Readmission')
    ),

    measures AS (
        SELECT
            1 AS measure_order,
            CAST('paid_members_by_payment_method' AS varchar(40)) AS measure,
            CAST(rpm.payment_method_name AS nvarchar(100)) AS category,
            CAST(COUNT(*) AS decimal(19, 4)) AS value
        FROM paid_members AS pm
        INNER JOIN Layercake.silv_ref_payment_method AS rpm
            ON rpm.id = pm.payment_method_id
        GROUP BY rpm.payment_method_name

        UNION ALL

        SELECT
            2,
            'corporate_paid_members',
            NULL,
            CAST(c.corporate_paid_members AS decimal(19, 4))
        FROM corporate AS c

        UNION ALL

        SELECT
            3,
            'corporate_share_pct',
            NULL,
            CAST(
                ROUND(100.0 * c.corporate_paid_members / NULLIF(c.paid_members, 0), 1) AS decimal(5, 1)
            )
        FROM corporate AS c

        UNION ALL

        SELECT
            4,
            'invoiced_subtotal_gbp_total',
            NULL,
            CAST(a.invoiced_subtotal_gbp_total AS decimal(19, 4))
        FROM amounts AS a

        UNION ALL

        SELECT
            5,
            'subs_amount_gbp_total',
            NULL,
            CAST(a.subs_amount_gbp_total AS decimal(19, 4))
        FROM amounts AS a

        UNION ALL

        SELECT
            6,
            'paid_members_by_concession_type',
            CAST(rct.concession_type_name AS nvarchar(100)),
            CAST(COUNT(*) AS decimal(19, 4))
        FROM paid_members AS pm
        INNER JOIN Layercake.silv_ref_concession_type AS rct
            ON rct.id = pm.concession_type_id
        GROUP BY rct.concession_type_name
    )

    SELECT
        @last_full_year AS campaign_year,
        m.measure,
        m.category,
        m.value
    FROM measures AS m
    ORDER BY m.measure_order, m.category;
END;
GO
